function worldDecor(){// battlefield landmarks
const posts=[{x:560,type:'sandbag'},{x:1120,type:'wire'},{x:1720,type:'sandbag'},{x:2250,type:'wire'},{x:2780,type:'ruin'},{x:3430,type:'sandbag'},{x:4170,type:'flare'}];for(const p of posts){let x=p.x-cam;if(x<-100||x>W+100)continue;if(p.type==='sandbag'){for(let i=0;i<5;i++){ellipse(x+(i%3)*28-27,ground-9-Math.floor(i/3)*14,20,10,'#4c4a3a');ellipse(x+(i%3)*28-27,ground-11-Math.floor(i/3)*14,17,7,'#656047');line(x-31+(i%3)*28,ground-10-Math.floor(i/3)*14,x-22+(i%3)*28,ground-9-Math.floor(i/3)*14,'#252920',2)}}else if(p.type==='wire'){for(let i=0;i<5;i++){line(x-54+i*27,ground-4,x-42+i*27,ground-40,'#575547',2);line(x-54+i*27,ground-27,x+50,ground-16,'#777362',1);line(x-52+i*27,ground-17,x+52,ground-31,'#777362',1)}}else if(p.type==='ruin'){rect(x-43,ground-135,86,135,'#202620');rect(x-32,ground-126,22,93,'#111714');rect(x+15,ground-110,20,55,'#111714');line(x-45,ground-135,x-28,ground-153,'#494c3a',5);line(x+19,ground-109,x+62,ground-126,'#3f4537',5);rect(x-52,ground-5,106,5,'#56604b')}else{rect(x-2,ground-82,5,82,'#645a46');line(x,ground-79,x+49,ground-100,'#574d40',3);ellipse(x+51,ground-102,8,11,'#c7443d');ellipse(x+51,ground-102,22,23,'#c7443d22');}}
}
function drawEnemy(e){let x=e.x-cam;if(x<-80||x>W+80)return;ctx.save();if(e.type==='brute'){ctx.translate(x,e.y-8);ctx.scale(1.35,1.35);drawSoldier(0,0,e.dir,t*1.6,0,true);rect(-20,-8,40,4,'#34251e');ctx.restore()}else{drawSoldier(x,e.y,e.dir,t*1.7,0,true)}if(e.type==='rifle'){line(x+e.dir*11,e.y+25,x+e.dir*47,e.y+22,'#171c19',4)}if(e.hp<3){rect(x-18,e.y-18,36,3,'#222');rect(x-18,e.y-18,36*Math.max(0,e.hp/3),3,'#bd5143')}}
function drawPickup(p){let x=p.x-cam,y=p.y+Math.sin(t*3+p.x)*4;if(x<-30||x>W+30)return;ellipse(x,y,17,17,p.type==='med'?'#9b393322':'#a9d84a22');ellipse(x,y,9,9,p.type==='med'?'#a6473e':'#b8d85c');ctx.fillStyle='#19211a';ctx.font='bold 14px sans-serif';ctx.textAlign='center';ctx.fillText(p.type==='med'?'✚':'▰',x,y+5)}
function drawBullet(b){ellipse(b.x-cam,b.y,6,3,b.enemy?'#d35c47':'#e3ce7b');ellipse(b.x-cam,b.y,13,6,b.enemy?'#d35c4733':'#e3ce7b33')}
function hud(){// top vignette and field instrument UI
let g=ctx.createLinearGradient(0,0,0,105);g.addColorStop(0,'#080d0dd9');g.addColorStop(1,'#080d0d00');rect(0,0,W,110,g);ctx.textAlign='left';ctx.fillStyle='#d9dfcf';ctx.font='700 18px "Barlow Condensed",sans-serif';ctx.letterSpacing='3px';ctx.fillText('FIELD REPORT 07',30,31);ctx.fillStyle='#889488';ctx.font='600 12px "Barlow Condensed",sans-serif';ctx.fillText('THE HOLLOW MARCH  /  NIGHT 3',30,49);
for(let i=0;i<player.maxHp;i++){ctx.fillStyle=i<player.hp?'#b64c42':'#343c36';ctx.fillRect(30+i*25,65,18,8);ctx.strokeStyle='#111';ctx.strokeRect(30+i*25,65,18,8)}ctx.fillStyle='#bdc5b7';ctx.font='600 13px "Barlow Condensed",sans-serif';ctx.fillText('VITALS',30,91);ctx.fillStyle='#d8d8c6';ctx.font='700 18px "Barlow Condensed",sans-serif';ctx.fillText('▰  '+String(player.ammo).padStart(2,'0'),190,75);ctx.fillStyle='#7d897e';ctx.font='600 11px "Barlow Condensed",sans-serif';ctx.fillText('9MM',190,91);
// mission tracker
ctx.textAlign='right';ctx.fillStyle='#b8d85c';ctx.font='700 15px "Barlow Condensed",sans-serif';ctx.fillText(signal?'SIGNAL FOUND — REACH EXTRACTION':'OBJECTIVE: FIND THE SIGNAL',W-30,31);ctx.fillStyle='#8c988d';ctx.font='600 12px "Barlow Condensed",sans-serif';ctx.fillText('DISTANCE   '+Math.max(0,Math.floor((worldW-player.x)/10))+' M',W-30,51);let bx=W-230,by=68;rect(bx,by,200,4,'#39423b');rect(bx,by,200*Math.min(player.x/worldW,1),4,'#a8c956');ellipse(bx+200*Math.min(player.x/worldW,1),by+2,4,4,'#d7e78c');
// bottom hints
ctx.textAlign='center';ctx.fillStyle='#89948a';ctx.font='600 12px "Barlow Condensed",sans-serif';ctx.fillText('A / D  MOVE     SPACE  JUMP     J  FIRE     K  MELEE     R  RESTART',W/2,H-19);
}
function draw(){ctx.setTransform(scale,0,0,scale,0,0);ctx.clearRect(0,0,W,H);ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);drawSky();worldDecor();drawGround();for(let p of pickups)drawPickup(p);for(let e of foes)if(e.hp>0)drawEnemy(e);for(let b of bullets)drawBullet(b);for(let b of enemyBullets)drawBullet(b);for(let p of particles){ellipse(p.x-cam,p.y,p.r,p.r,p.c)}drawSoldier(player.x-cam,player.y,player.face,player.anim,player.knife,false);if(player.muzzle>0){ellipse(player.x-cam+player.face*42,player.y+22,16*player.muzzle,6*player.muzzle,'#f6df8299')};
// extraction gate
let gx=worldW-120-cam;if(gx>-150&&gx<W+150){rect(gx-42,ground-150,84,150,'#111a16');rect(gx-34,ground-142,68,142,'#2c3b2b');rect(gx-28,ground-136,56,136,'#0a1110');ellipse(gx,ground-125,40,60,'#a0d35418');line(gx-51,ground-151,gx+49,ground-151,'#697552',5);ctx.fillStyle='#b8d85c';ctx.font='700 13px sans-serif';ctx.textAlign='center';ctx.fillText('EXTRACTION',gx,ground-164)}
// vignette overlay
let v=ctx.createRadialGradient(W/2,H/2,150,W/2,H/2,760);v.addColorStop(.55,'#0000');v.addColorStop(1,'#020605c9');rect(0,0,W,H,v);if(flash>0){rect(0,0,W,H,'#d8ead2'+Math.floor(flash*50).toString(16).padStart(2,'0'))}ctx.restore();hud();}

