function draw(){ctx.setTransform(scale,0,0,scale,0,0);ctx.clearRect(0,0,W,H);ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);drawSky();worldDecor();drawGround();for(let p of pickups)drawPickup(p);for(let e of foes)if(e.hp>0)drawEnemy(e);for(let b of bullets)drawBullet(b);for(let b of enemyBullets)drawBullet(b);for(let p of particles)ellipse(p.x-cam,p.y,p.r,p.r,p.c);drawSoldier(player.x-cam,player.y,player.face,player.anim,player.knife,false);if(player.muzzle>0)ellipse(player.x-cam+player.face*42,player.y+22,16*player.muzzle,6*player.muzzle,'#f6df8299');
let gx=worldW-120-cam;if(gx>-150&&gx<W+150){rect(gx-42,ground-150,84,150,'#111a16');rect(gx-34,ground-142,68,142,'#2c3b2b');rect(gx-28,ground-136,56,136,'#0a1110');ellipse(gx,ground-125,40,60,'#a0d35418');line(gx-51,ground-151,gx+49,ground-151,'#697552',5);ctx.fillStyle='#b8d85c';ctx.font='700 13px sans-serif';ctx.textAlign='center';ctx.fillText('EXTRACTION',gx,ground-164)}let v=ctx.createRadialGradient(W/2,H/2,150,W/2,H/2,760);v.addColorStop(.55,'#0000');v.addColorStop(1,'#020605c9');rect(0,0,W,H,v);if(flash>0)rect(0,0,W,H,'#d8ead2'+Math.floor(flash*50).toString(16).padStart(2,'0'));ctx.restore();if(gameState==='playing')hud()}
let fireWait=0,knifeWait=0,jumpWas=false;
function puff(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*130,vy:(Math.random()-.8)*120,r:1+Math.random()*3,life:.25+Math.random()*.5,c:color})}
function fire(){if(fireWait>0||player.ammo<=0)return;fireWait=.22;player.ammo--;player.muzzle=.12;bullets.push({x:player.x+player.face*39,y:player.y+23,vx:player.face*690,life:1.5,enemy:false});puff(player.x+player.face*41,player.y+22,'#dfbd7099',3)}
function melee(){if(knifeWait>0)return;knifeWait=.52;player.knife=.18;for(let e of foes){if(e.hp>0&&Math.abs(e.x-player.x)<76&&Math.abs(e.y-player.y)<45&&Math.sign(e.x-player.x)===player.face){e.hp-=2;shake=3;puff(e.x,e.y+20,'#b34c43',11)}}}
function hurt(dmg=1){if(player.invuln>0)return;player.hp-=dmg;player.invuln=1.1;shake=10;flash=.4;puff(player.x,player.y+20,'#af443e',12);if(player.hp<=0)finish(false)}
function finish(win){gameState=win?'win':'dead';overlay.classList.remove('hide');document.querySelector('.panel').innerHTML=`<div class="eyebrow">${win?'FIELD REPORT 07 · COMPLETE':'FIELD REPORT 07 · LOST CONTACT'}</div><h1 class="title">${win?'Signal':'The fog'}<span>${win?'Sent':'Takes all'}</span></h1><p class="copy">${win?'The flare burns through the dark. Somewhere beyond the wire, an engine answers. You made it out.':'Your signal dies in the trench. The march goes on without you.'}<br><br>FIELD DISTANCE: ${Math.min(100,Math.floor(player.x/worldW*100))}%</p><button class="start" id="again">${win?'Walk away':'Try again'}&nbsp; ↻</button><div class="keys"><b>R</b> restart at any time</div>`;document.getElementById('again').onclick=start}
function update(dt){t+=dt;fireWait-=dt;knifeWait-=dt;player.invuln-=dt;player.knife=Math.max(0,player.knife-dt);player.muzzle=Math.max(0,player.muzzle-dt);flash=Math.max(0,flash-dt);shake=Math.max(0,shake-dt*20);let dir=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);if(dir){player.face=dir;player.vx=dir*235}else player.vx*=Math.pow(.001,dt);player.anim+=dt*Math.abs(player.vx)/50;
if((keys[' ']||keys.w||keys.arrowup)&&player.grounded&&!jumpWas){player.vy=-570;player.grounded=false;puff(player.x,ground,'#69664f',5)}jumpWas=!!(keys[' ']||keys.w||keys.arrowup);if(keys.j||keys.x)fire();if(keys.k||keys.z)melee();player.x=Math.max(18,Math.min(worldW-25,player.x+player.vx*dt));player.vy+=1450*dt;player.y+=player.vy*dt;let foot=player.y+player.h;if(foot>=ground&&!overPit(player.x)){player.y=ground-player.h;player.vy=0;player.grounded=true}else player.grounded=false;if(player.y>H+40){hurt(99);if(gameState==='playing'){player.x=Math.max(checkpoint,player.x-180);player.y=ground-player.h;player.vy=0}}
cam=Math.max(0,Math.min(worldW-W,player.x-W*.36));if(player.x>1450)checkpoint=1380;if(player.x>2800)checkpoint=2750;
for(let e of foes){if(e.hp<=0)continue;let dx=player.x-e.x;e.dir=dx<0?-1:1;e.cd-=dt;if(e.type==='ghoul'||e.type==='brute'){if(Math.abs(dx)<350)e.x+=e.dir*(e.type==='brute'?42:58)*dt;if(Math.abs(dx)<43&&Math.abs(player.y-e.y)<40)hurt()}else if(Math.abs(dx)<520&&e.cd<=0){e.cd=1.65+Math.random()*.8;enemyBullets.push({x:e.x+e.dir*25,y:e.y+23,vx:e.dir*300,life:2,enemy:true})}}
for(let b of bullets){b.x+=b.vx*dt;b.life-=dt;for(let e of foes)if(e.hp>0&&Math.abs(b.x-e.x)<24&&Math.abs(b.y-(e.y+22))<29){e.hp--;b.life=0;puff(e.x,e.y+22,'#bd5547',5);if(e.hp<=0){score+=100;puff(e.x,e.y,'#202820',13)}}}bullets=bullets.filter(b=>b.life>0&&b.x>cam-50&&b.x<cam+W+60);
for(let b of enemyBullets){b.x+=b.vx*dt;b.life-=dt;if(Math.abs(b.x-player.x)<22&&Math.abs(b.y-(player.y+25))<30){b.life=0;hurt()}}enemyBullets=enemyBullets.filter(b=>b.life>0);
for(let p of pickups)if(!p.got&&Math.abs(player.x-p.x)<29&&Math.abs(player.y+player.h/2-p.y)<48){p.got=true;if(p.type==='med')player.hp=Math.min(player.maxHp,player.hp+2);else player.ammo+=8;puff(p.x,p.y,'#b8d85c',10)}if(player.x>3980)signal=true;if(player.x>=worldW-90&&signal)finish(true);
for(let p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=220*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);}
function loop(now){if(gameState!=='playing')return;let dt=Math.min(.033,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(loop)}
reset();draw();
})();
</script>
</body>
</html>

